afterAll(() => cleanup());

describe("lifecycle", () => {
  it("works", async () => {
    const off = registerActivityListeners();
    const t = await createTenant("life");
    await usageRepo.recomputeUsage(t.org.id);
    await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id));
    const [inv] = await invitationService.inviteMembers(t.actors.owner, { orgId: t.org.id, invites: [{ email: "x@y.z", role: "member" }] });
    const events: string[] = [];
    subscribe("organization.deleted", (p) => { events.push("del:" + p.slug + ":" + p.actorId); });
    subscribe("organization.restored", (p) => { events.push("res:" + p.slug + ":" + p.actorId); });

    await orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: t.org.slug });
    await expect(orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: t.org.slug })).rejects.toBeInstanceOf(AlreadyArchivedError);
    expect(await orgService.listOrganizationsForUser(t.userIds.owner)).toHaveLength(0);
    expect(await notify(t.org.id, "issue_assigned", [t.userIds.admin], { title: "a", body: "b", href: "/", actorId: null })).toHaveLength(0);
    const r = await runUsageRollupJob(new Date());
    expect(r.processed).toBe(0);

    await expect(orgService.restoreOrganization(t.userIds.admin, t.org.id)).rejects.toBeInstanceOf(PermissionDeniedError);
    const outsider = await userRepo.insertUser({ email: "o@o.o", name: "o", passwordHash: "x" });
    await expect(orgService.restoreOrganization(outsider.id, t.org.id)).rejects.toBeInstanceOf(NotFoundError);
    const restored = await orgService.restoreOrganization(t.userIds.owner, t.org.id);
    expect(restored.archivedAt).toBeNull();
    await orgService.restoreOrganization(t.userIds.owner, t.org.id);
    expect(events).toEqual([`del:life:${t.userIds.owner}`, `res:life:${t.userIds.owner}`]);
    const audit = await activityRepo.listActivity(activityFilterSchema.parse({ orgId: t.org.id, action: ["organization.deleted", "organization.restored"] }));
    expect(audit.items.map((e) => e.action).sort()).toEqual(["organization.deleted", "organization.restored"]);

    // delete again, backdate, purge
    await orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: t.org.slug });
    const s = await sessionRepo.createSession(t.userIds.owner, "hash1", new Date(Date.now() + 1e9).toISOString() as never);
    getDb().update(sessions).set({ activeOrgId: t.org.id }).run();
    const now = new Date();
    const early = await runCleanupArchivedJob(new Date(now.getTime() + 29 * 86400000));
    expect(getDb().select().from(organizations).where(eq(organizations.id, t.org.id)).all()).toHaveLength(1);
    const res = await runCleanupArchivedJob(new Date(now.getTime() + 30 * 86400000 + 1000));
    expect(res.processed).toBeGreaterThan(0);
    expect(getDb().select().from(organizations).where(eq(organizations.id, t.org.id)).all()).toHaveLength(0);
    expect(getDb().select().from(members).where(eq(members.orgId, t.org.id)).all()).toHaveLength(0);
    expect(getDb().select().from(issues).where(eq(issues.orgId, t.org.id)).all()).toHaveLength(0);
    expect(getDb().select().from(sessions).all()[0]?.activeOrgId).toBeNull();
    await expect(orgService.restoreOrganization(t.userIds.owner, t.org.id)).rejects.toBeInstanceOf(NotFoundError);
    const again = await orgService.createOrganization(outsider.id, { name: "n", slug: "life", plan: "free" });
    expect(again.slug).toBe("life");
    void inv; void s; void early; void searchIndex;
    off();
  });
});
